import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

cuda_decl = r"""
#include <torch/extension.h>
torch::Tensor cute_sigmoid_forward(torch::Tensor x);
"""

cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cute/tensor.hpp>

using namespace cute;

// Vectorized sigmoid kernel operating on float4 chunks using CUTE tensors
__global__ void sigmoid_kernel_vec4(const float* __restrict__ X,
                                     float* __restrict__ Y,
                                     int64_t N4)
{
  int64_t idx = (int64_t)blockIdx.x * (int64_t)blockDim.x + (int64_t)threadIdx.x;
  if (idx >= N4) return;

  // Represent the buffers as CUTE tensors of float4 elements
  auto mX4 = make_tensor(make_gmem_ptr(reinterpret_cast<const float4*>(X)),
                          make_shape(N4));
  auto mY4 = make_tensor(make_gmem_ptr(reinterpret_cast<float4*>(Y)),
                          make_shape(N4));

  float4 v = mX4(idx);
  float4 r;
  r.x = 1.0f / (1.0f + __expf(-v.x));
  r.y = 1.0f / (1.0f + __expf(-v.y));
  r.z = 1.0f / (1.0f + __expf(-v.z));
  r.w = 1.0f / (1.0f + __expf(-v.w));
  mY4(idx) = r;
}

// Scalar fallback kernel for any leftover elements (N % 4 != 0)
__global__ void sigmoid_kernel_scalar(const float* __restrict__ X,
                                       float* __restrict__ Y,
                                       int64_t Nrem)
{
  int64_t idx = (int64_t)blockIdx.x * (int64_t)blockDim.x + (int64_t)threadIdx.x;
  if (idx >= Nrem) return;

  auto mX = make_tensor(make_gmem_ptr(X), make_shape(Nrem));
  auto mY = make_tensor(make_gmem_ptr(Y), make_shape(Nrem));

  float v = mX(idx);
  mY(idx) = 1.0f / (1.0f + __expf(-v));
}

torch::Tensor cute_sigmoid_forward(torch::Tensor x) {
  TORCH_CHECK(x.is_cuda(), "x must be a CUDA tensor");
  TORCH_CHECK(x.scalar_type() == at::kFloat, "x must be float32");

  auto x_c = x.contiguous();
  auto y = torch::empty_like(x_c);

  int64_t N = x_c.numel();
  int64_t N4 = N / 4;
  int64_t rem = N - N4 * 4;

  const float* xptr = x_c.data_ptr<float>();
  float* yptr = y.data_ptr<float>();

  cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();

  constexpr int Threads = 256;

  if (N4 > 0) {
    int64_t blocks = (N4 + Threads - 1) / Threads;
    sigmoid_kernel_vec4<<<(unsigned)blocks, Threads, 0, stream>>>(xptr, yptr, N4);
  }

  if (rem > 0) {
    int64_t offset = N4 * 4;
    int64_t blocks = (rem + Threads - 1) / Threads;
    sigmoid_kernel_scalar<<<(unsigned)blocks, Threads, 0, stream>>>(
        xptr + offset, yptr + offset, rem);
  }

  auto err = cudaGetLastError();
  TORCH_CHECK(err == cudaSuccess, "cute_sigmoid_forward launch failed: ", cudaGetErrorString(err));

  return y;
}
"""

cute_sigmoid_ext = load_inline(
    name="cute_sigmoid_ext",
    cpp_sources=cuda_decl,
    cuda_sources=cuda_src,
    functions=["cute_sigmoid_forward"],
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3"],
    extra_include_paths=[
        "/home/tarasaba/PycharmProjects/cutegen_test/cutegen/cutlass/include",
        "/home/tarasaba/PycharmProjects/cutegen_test/cutegen/cutlass/include/cute/",
    ],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    Simple model that performs a Sigmoid activation using a custom CUTE kernel.
    """
    def __init__(self):
        super(ModelNew, self).__init__()
        self._ext = cute_sigmoid_ext

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return self._ext.cute_sigmoid_forward(x)

